// Orders API of an existing service: hand-written, never generated by gherkin-ai.
import express from 'express';

export const orders = express.Router();
const store = new Map();

orders.post('/orders', (req, res) => {
  if (!req.user) return res.status(401).json({ detail: 'sign in first' });
  if (!Array.isArray(req.body?.items) || req.body.items.length === 0) return res.status(422).json({ detail: 'items are required' });
  const order = { id: String(store.size + 1), status: 'PENDING', items: req.body.items };
  store.set(order.id, order);
  res.status(201).json(order);
});

orders.post('/orders/:id/cancel', (req, res) => {
  const order = store.get(req.params.id);
  if (!order) return res.status(404).json({ detail: 'order not found' });
  order.status = 'CANCELLED';
  res.json(order);
});
